entity, the expected value can be either a schema (schema) or a table
(schema.table)

=item * C<< $msg->entity_name_prefix() >> / C<< $msg->entity_name_prefix($value) >>

Type: C<String>

Optional. The rule should be applied to entities whose non-qualified name
starts with the given prefix.

=item * C<< $msg->entity_name_suffix() >> / C<< $msg->entity_name_suffix($value) >>

Type: C<String>

Optional. The rule should be applied to entities whose non-qualified name
ends with the given suffix.

=item * C<< $msg->entity_name_contains() >> / C<< $msg->entity_name_contains($value) >>

Type: C<String>

Optional. The rule should be applied to entities whose non-qualified name
contains the given string.

=item * C<< $msg->entities() >> / C<< $msg->entities($value) >>

Type: C<String>

Optional. The rule should be applied to specific entities defined by their
fully qualified names.

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MappingRule

Definition of a transformation that is to be applied to a group of entities
in the source schema. Several such transformations can be applied to an
entity sequentially to define the corresponding entity in the target schema.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Full name of the mapping rule resource, in the form of:
projects/{project}/locations/{location}/conversionWorkspaces/{set}/mappingRule/{rule}.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Optional. A human readable name

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::MappingRule::State>)

Optional. The mapping rule state

=item * C<< $msg->rule_scope() >> / C<< $msg->rule_scope($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::DatabaseEntityType>)

Required. The rule scope

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MappingRuleFilter>)

Required. The rule filter

=item * C<< $msg->rule_order() >> / C<< $msg->rule_order($value) >>

Type: C<Int64>

Required. The order in which the rule is applied. Lower order rules are
applied before higher value rules so they may end up being overridden.

=item * C<< $msg->revision_id() >> / C<< $msg->revision_id($value) >>

Type: C<String>

Output only. The revision ID of the mapping rule.
A new revision is committed whenever the mapping rule is changed in any
way. The format is an 8-character hexadecimal string.

=item * C<< $msg->revision_create_time() >> / C<< $msg->revision_create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The timestamp that the revision was created.

=item * C<< $msg->single_entity_rename() >> / C<< $msg->single_entity_rename($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SingleEntityRename>)

Optional. Rule to specify how a single entity should be renamed.

=item * C<< $msg->multi_entity_rename() >> / C<< $msg->multi_entity_rename($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MultiEntityRename>)

Optional. Rule to specify how multiple entities should be renamed.

=item * C<< $msg->entity_move() >> / C<< $msg->entity_move($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityMove>)

Optional. Rule to specify how multiple entities should be relocated into
a different schema.

=item * C<< $msg->single_column_change() >> / C<< $msg->single_column_change($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SingleColumnChange>)

Optional. Rule to specify how a single column is converted.

=item * C<< $msg->multi_column_data_type_change() >> / C<< $msg->multi_column_data_type_change($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MultiColumnDatatypeChange>)

Optional. Rule to specify how multiple columns should be converted to a
different data type.

=item * C<< $msg->conditional_column_set_value() >> / C<< $msg->conditional_column_set_value($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::ConditionalColumnSetValue>)

Optional. Rule to specify how the data contained in a column should be
transformed (such as trimmed, rounded, etc) provided that the data meets
certain criteria.

=item * C<< $msg->convert_rowid_column() >> / C<< $msg->convert_rowid_column($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::ConvertRowIdToColumn>)

Optional. Rule to specify how multiple tables should be converted with an
additional rowid column.

=item * C<< $msg->set_table_primary_key() >> / C<< $msg->set_table_primary_key($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SetTablePrimaryKey>)

Optional. Rule to specify the primary key for a table

=item * C<< $msg->single_package_change() >> / C<< $msg->single_package_change($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SinglePackageChange>)

Optional. Rule to specify how a single package is converted.

=item * C<< $msg->source_sql_change() >> / C<< $msg->source_sql_change($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SourceSqlChange>)

Optional. Rule to change the sql code for an entity, for example,
function, procedure.

=item * C<< $msg->filter_table_columns() >> / C<< $msg->filter_table_columns($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::FilterTableColumns>)

Optional. Rule to specify the list of columns to include or exclude from
a table.

=back

