=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SingleColumnChange

Options to configure rule type SingleColumnChange.
The rule is used to change the properties of a column.

The rule filter field can refer to one entity.

The rule scope can be one of: Column.

When using this rule, if a field is not specified than the destination
column's configuration will be the same as the one in the source column..

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->data_type() >> / C<< $msg->data_type($value) >>

Type: C<String>

Optional. Column data type name.

=item * C<< $msg->charset() >> / C<< $msg->charset($value) >>

Type: C<String>

Optional. Charset override - instead of table level charset.

=item * C<< $msg->collation() >> / C<< $msg->collation($value) >>

Type: C<String>

Optional. Collation override - instead of table level collation.

=item * C<< $msg->length() >> / C<< $msg->length($value) >>

Type: C<Int64>

Optional. Column length - e.g. 50 as in varchar (50) - when relevant.

=item * C<< $msg->precision() >> / C<< $msg->precision($value) >>

Type: C<Int32>

Optional. Column precision - e.g. 8 as in double (8,2) - when relevant.

=item * C<< $msg->scale() >> / C<< $msg->scale($value) >>

Type: C<Int32>

Optional. Column scale - e.g. 2 as in double (8,2) - when relevant.

=item * C<< $msg->fractional_seconds_precision() >> / C<< $msg->fractional_seconds_precision($value) >>

Type: C<Int32>

Optional. Column fractional seconds precision - e.g. 2 as in timestamp (2)
- when relevant.

=item * C<< $msg->array() >> / C<< $msg->array($value) >>

Type: C<Bool>

Optional. Is the column of array type.

=item * C<< $msg->array_length() >> / C<< $msg->array_length($value) >>

Type: C<Int32>

Optional. The length of the array, only relevant if the column type is an
array.

=item * C<< $msg->nullable() >> / C<< $msg->nullable($value) >>

Type: C<Bool>

Optional. Is the column nullable.

=item * C<< $msg->auto_generated() >> / C<< $msg->auto_generated($value) >>

Type: C<Bool>

Optional. Is the column auto-generated/identity.

=item * C<< $msg->udt() >> / C<< $msg->udt($value) >>

Type: C<Bool>

Optional. Is the column a UDT (User-defined Type).

=item * C<< $msg->custom_features() >> / C<< $msg->custom_features($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Optional. Custom engine specific features.

=item * C<< $msg->set_values() >> / C<< $msg->set_values($value) >>

Type: C<String>

Optional. Specifies the list of values allowed in the column.

=item * C<< $msg->comment() >> / C<< $msg->comment($value) >>

Type: C<String>

Optional. Comment associated with the column.

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MultiColumnDatatypeChange

Options to configure rule type MultiColumnDatatypeChange.
The rule is used to change the data type and associated properties of
multiple columns at once.

The rule filter field can refer to one or more entities.

The rule scope can be one of:Column.

This rule requires additional filters to be specified beyond the basic rule
filter field, which is the source data type, but the rule supports additional
filtering capabilities such as the minimum and maximum field length. All
additional filters which are specified are required to be met in order for
the rule to be applied (logical AND between the fields).

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->source_data_type_filter() >> / C<< $msg->source_data_type_filter($value) >>

Type: C<String>

Required. Filter on source data type.

=item * C<< $msg->source_text_filter() >> / C<< $msg->source_text_filter($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SourceTextFilter>)

Optional. Filter for text-based data types like varchar.

=item * C<< $msg->source_numeric_filter() >> / C<< $msg->source_numeric_filter($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SourceNumericFilter>)

Optional. Filter for fixed point number data types such as
NUMERIC/NUMBER.

=item * C<< $msg->new_data_type() >> / C<< $msg->new_data_type($value) >>

Type: C<String>

Required. New data type.

=item * C<< $msg->override_length() >> / C<< $msg->override_length($value) >>

Type: C<Int64>

Optional. Column length - e.g. varchar (50) - if not specified and relevant
uses the source column length.

=item * C<< $msg->override_scale() >> / C<< $msg->override_scale($value) >>

Type: C<Int32>

Optional. Column scale - when relevant - if not specified and relevant
uses the source column scale.

=item * C<< $msg->override_precision() >> / C<< $msg->override_precision($value) >>

Type: C<Int32>

Optional. Column precision - when relevant - if not specified and relevant
uses the source column precision.

=item * C<< $msg->override_fractional_seconds_precision() >> / C<< $msg->override_fractional_seconds_precision($value) >>

Type: C<Int32>

Optional. Column fractional seconds precision - used only for timestamp
based datatypes - if not specified and relevant uses the source column
fractional seconds precision.

=item * C<< $msg->custom_features() >> / C<< $msg->custom_features($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Optional. Custom engine specific features.

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SourceTextFilter

Filter for text-based data types like varchar.

