=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::RoundToScale

This allows the data to change scale, for example if the source is 2 digits
after the decimal point, specify round to scale value = 2. If for example the
value needs to be converted to an integer, use round to scale value = 0.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->scale() >> / C<< $msg->scale($value) >>

Type: C<Int32>

Required. Scale value to be used

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::DatabaseEntity

The base entity type for all the database related entities.
The message contains the entity name, the name of its parent, the entity
type, and the specific details per entity type.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->short_name() >> / C<< $msg->short_name($value) >>

Type: C<String>

The short name (e.g. table name) of the entity.

=item * C<< $msg->parent_entity() >> / C<< $msg->parent_entity($value) >>

Type: C<String>

The full name of the parent entity (e.g. schema name).

=item * C<< $msg->tree() >> / C<< $msg->tree($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::DatabaseEntity::TreeType>)

The type of tree the entity belongs to.

=item * C<< $msg->entity_type() >> / C<< $msg->entity_type($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::DatabaseEntityType>)

The type of the database entity (table, view, index, ...).

=item * C<< $msg->mappings() >> / C<< $msg->mappings($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityMapping>)

Details about entity mappings.
For source tree entities, this holds the draft entities which were
generated by the mapping rules.
For draft tree entities, this holds the source entities which were
converted to form the draft entity.
Destination entities will have no mapping details.

=item * C<< $msg->entity_ddl() >> / C<< $msg->entity_ddl($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityDdl>)

Details about the entity DDL script. Multiple DDL scripts are provided for
child entities such as a table entity will have one DDL for the table with
additional DDLs for each index, constraint and such.

=item * C<< $msg->issues() >> / C<< $msg->issues($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityIssue>)

Details about the various issues found for the entity.

=item * C<< $msg->database() >> / C<< $msg->database($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::DatabaseInstanceEntity>)

Database.

=item * C<< $msg->schema() >> / C<< $msg->schema($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SchemaEntity>)

Schema.

=item * C<< $msg->table() >> / C<< $msg->table($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::TableEntity>)

Table.

=item * C<< $msg->view() >> / C<< $msg->view($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::ViewEntity>)

View.

=item * C<< $msg->sequence() >> / C<< $msg->sequence($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SequenceEntity>)

Sequence.

=item * C<< $msg->stored_procedure() >> / C<< $msg->stored_procedure($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::StoredProcedureEntity>)

Stored procedure.

=item * C<< $msg->database_function() >> / C<< $msg->database_function($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::FunctionEntity>)

Function.

=item * C<< $msg->synonym() >> / C<< $msg->synonym($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::SynonymEntity>)

Synonym.

=item * C<< $msg->database_package() >> / C<< $msg->database_package($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::PackageEntity>)

Package.

=item * C<< $msg->udt() >> / C<< $msg->udt($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::UDTEntity>)

UDT.

=item * C<< $msg->materialized_view() >> / C<< $msg->materialized_view($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::MaterializedViewEntity>)

Materialized view.

=back

