=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::ColumnEntity

Column is not used as an independent entity, it is retrieved as part of a
Table entity.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Column name.

=item * C<< $msg->data_type() >> / C<< $msg->data_type($value) >>

Type: C<String>

Column data type.

=item * C<< $msg->charset() >> / C<< $msg->charset($value) >>

Type: C<String>

Charset override - instead of table level charset.

=item * C<< $msg->collation() >> / C<< $msg->collation($value) >>

Type: C<String>

Collation override - instead of table level collation.

=item * C<< $msg->length() >> / C<< $msg->length($value) >>

Type: C<Int64>

Column length - e.g. varchar (50).

=item * C<< $msg->precision() >> / C<< $msg->precision($value) >>

Type: C<Int32>

Column precision - when relevant.

=item * C<< $msg->scale() >> / C<< $msg->scale($value) >>

Type: C<Int32>

Column scale - when relevant.

=item * C<< $msg->fractional_seconds_precision() >> / C<< $msg->fractional_seconds_precision($value) >>

Type: C<Int32>

Column fractional second precision - used for timestamp based datatypes.

=item * C<< $msg->array() >> / C<< $msg->array($value) >>

Type: C<Bool>

Is the column of array type.

=item * C<< $msg->array_length() >> / C<< $msg->array_length($value) >>

Type: C<Int32>

If the column is array, of which length.

=item * C<< $msg->nullable() >> / C<< $msg->nullable($value) >>

Type: C<Bool>

Is the column nullable.

=item * C<< $msg->auto_generated() >> / C<< $msg->auto_generated($value) >>

Type: C<Bool>

Is the column auto-generated/identity.

=item * C<< $msg->udt() >> / C<< $msg->udt($value) >>

Type: C<Bool>

Is the column a UDT.

=item * C<< $msg->custom_features() >> / C<< $msg->custom_features($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Custom engine specific features.

=item * C<< $msg->set_values() >> / C<< $msg->set_values($value) >>

Type: C<String>

Specifies the list of values allowed in the column.
Only used for set data type.

=item * C<< $msg->comment() >> / C<< $msg->comment($value) >>

Type: C<String>

Comment associated with the column.

=item * C<< $msg->ordinal_position() >> / C<< $msg->ordinal_position($value) >>

Type: C<Int32>

Column order in the table.

=item * C<< $msg->default_value() >> / C<< $msg->default_value($value) >>

Type: C<String>

Default value of the column.

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::ConstraintEntity

Constraint is not used as an independent entity, it is retrieved
as part of another entity such as Table or View.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The name of the table constraint.

=item * C<< $msg->type() >> / C<< $msg->type($value) >>

Type: C<String>

Type of constraint, for example unique, primary key, foreign key (currently
only primary key is supported).

=item * C<< $msg->table_columns() >> / C<< $msg->table_columns($value) >>

Type: C<String>

Table columns used as part of the Constraint, for example primary key
constraint should list the columns which constitutes the key.

=item * C<< $msg->custom_features() >> / C<< $msg->custom_features($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Custom engine specific features.

=item * C<< $msg->reference_columns() >> / C<< $msg->reference_columns($value) >>

Type: C<String>

Reference columns which may be associated with the constraint. For example,
if the constraint is a FOREIGN_KEY, this represents the list of full names
of referenced columns by the foreign key.

=item * C<< $msg->reference_table() >> / C<< $msg->reference_table($value) >>

Type: C<String>

Reference table which may be associated with the constraint. For example,
if the constraint is a FOREIGN_KEY, this represents the list of full name
of the referenced table by the foreign key.

=item * C<< $msg->table_name() >> / C<< $msg->table_name($value) >>

Type: C<String>

Table which is associated with the constraint. In case the constraint
is defined on a table, this field is left empty as this information is
stored in parent_name. However, if constraint is defined on a view, this
field stores the table name on which the view is defined.

=back

=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::IndexEntity

Index is not used as an independent entity, it is retrieved as part of a
