=head2 Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityMapping

Details of the mappings of a database entity.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->source_entity() >> / C<< $msg->source_entity($value) >>

Type: C<String>

Source entity full name.
The source entity can also be a column, index or constraint using the
same naming notation schema.table.column.

=item * C<< $msg->draft_entity() >> / C<< $msg->draft_entity($value) >>

Type: C<String>

Target entity full name.
The draft entity can also include a column, index or constraint using the
same naming notation schema.table.column.

=item * C<< $msg->source_type() >> / C<< $msg->source_type($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::DatabaseEntityType>)

Type of source entity.

=item * C<< $msg->draft_type() >> / C<< $msg->draft_type($value) >>

Type: C<Enum> (L<Google::Cloud::Clouddms::V1::DatabaseEntityType>)

Type of draft entity.

=item * C<< $msg->mapping_log() >> / C<< $msg->mapping_log($value) >>

Type: C<Message> (L<Google::Cloud::Clouddms::V1::ConversionworkspaceResources::EntityMappingLogEntry>)

Entity mapping log entries.
Multiple rules can be effective and contribute changes to a converted
entity, such as a rule can handle the entity name, another rule can handle
an entity type. In addition, rules which did not change the entity are also
logged along with the reason preventing them to do so.

=back

